    $('seaVibeAddTripBtn')?.addEventListener('click',()=>{resetTripForm();switchTo('seaVibeTripNew');});$('seaVibeTripBackBtn')?.addEventListener('click',()=>switchTo('seaVibeTrips'));$('seaVibeTripDetailsBackBtn')?.addEventListener('click',()=>switchTo('seaVibeTrips'));$('seaVibeTripCancelBtn')?.addEventListener('click',()=>switchTo('seaVibeTrips'));
