    $('seaVibeTripForm')?.addEventListener('submit',async e=>{e.preventDefault();try{showStatus('seaVibeTripFormStatus',t('seaVibe.common.saving','جاري الحفظ...'));await window.SeaVibeService.saveTrip({id:$('seaVibeTripId').value||'',date:$('seaVibeTripDate').value,startTime:$('seaVibeTripStartTime').value,durationHours:Number($('seaVibeTripDuration').value),peopleCount:Number($('seaVibeTripPeople').value),tripTypeId:$('seaVibeTripType').value,totalValue:Number($('seaVibeTripValue').value||0),notes:$('seaVibeTripNotes').value});showStatus('seaVibeTripFormStatus',t('seaVibe.trip.saved','تم حفظ الرحلة.'),'success');setTimeout(()=>switchTo('seaVibeTrips'),250);}catch(err){showStatus('seaVibeTripFormStatus',err.message,'error');}});
