    $('seaVibeExpenseForm')?.addEventListener('submit',async e=>{e.preventDefault();try{const rows=collectExpenses();if(!rows.length)throw new Error(t('seaVibe.validation.expenseRequired','أضف مصروفًا واحدًا على الأقل.'));showStatus('seaVibeExpenseFormStatus',t('seaVibe.common.saving','جاري الحفظ...'));const editState=currentExpenseEditingState();if(editState.groupId){const groupId=editState.groupId,returnView=editState.returnView||'seaVibeTreasury';await window.SeaVibeService.updateExpenseMovement(groupId,rows);showStatus('seaVibeExpenseFormStatus',t('seaVibe.expense.movementUpdated','تم تعديل حركة المصروفات.'),'success');setExpenseEditingState('','');setTimeout(()=>switchTo(returnView),180);}else{await window.SeaVibeService.addExpenses(rows);showStatus('seaVibeExpenseFormStatus',t('seaVibe.expense.saved','تم حفظ المصروفات.'),'success');resetExpenseForm($('seaVibeExpenseScope').value);}}catch(err){showStatus('seaVibeExpenseFormStatus',err.message,'error');}});
    $('seaVibeGeneralAddBtn')?.addEventListener('click',()=>{resetExpenseForm('general');switchTo('seaVibeExpenseNew');});$('seaVibeAddAssetBtn')?.addEventListener('click',()=>showAssetForm());$('seaVibeAssetCancelBtn')?.addEventListener('click',()=>$('seaVibeAssetForm').classList.add('hidden'));$('seaVibeAssetForm')?.addEventListener('submit',async e=>{e.preventDefault();await window.SeaVibeService.saveAsset({id:$('seaVibeAssetId').value||'',name:$('seaVibeAssetName').value,initialValue:Number($('seaVibeAssetValue').value||0),notes:$('seaVibeAssetNotes').value,isActive:true});$('seaVibeAssetForm').classList.add('hidden');renderAssets();});
