    $('seaVibeZawelTopupBtn')?.addEventListener('click',()=>{resetZawelTopupForm();$('seaVibeZawelTopupForm').classList.remove('hidden');$('seaVibeZawelTopupPoints').focus();});
    $('seaVibeZawelTopupCancel')?.addEventListener('click',()=>{resetZawelTopupForm();$('seaVibeZawelTopupForm').classList.add('hidden');showStatus('seaVibeZawelStatus','');});
    $('seaVibeZawelTopupPoints')?.addEventListener('input',()=>{$('seaVibeZawelTopupCost').value=money(zawelCost($('seaVibeZawelTopupPoints').value));});if($('seaVibeZawelTopupDate'))$('seaVibeZawelTopupDate').value=localDateIso();
    $('seaVibeZawelTopupForm')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;try{showStatus('seaVibeZawelStatus',t('seaVibe.common.saving','جاري الحفظ...'));const points=Number($('seaVibeZawelTopupPoints').value),notes=$('seaVibeZawelTopupNotes').value,transactionDate=$('seaVibeZawelTopupDate').value;if(editingZawelTopupId){await window.SeaVibeService.updateZawelTopup(editingZawelTopupId,points,notes,transactionDate);showStatus('seaVibeZawelStatus',t('seaVibe.zawel.topupUpdated','تم تعديل حركة الشحن.'),'success');}else{await window.SeaVibeService.topupZawel(points,notes,transactionDate);showStatus('seaVibeZawelStatus',t('seaVibe.zawel.topupSaved','تم شحن رصيد زاول.'),'success');}resetZawelTopupForm();form?.classList.add('hidden');renderZawel();renderTreasury();}catch(err){showStatus('seaVibeZawelStatus',err.message,'error');}});
