    $('seaVibeFuelTopupForm')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;try{showStatus('seaVibeFuelStatus',t('seaVibe.common.saving','جاري الحفظ...'));const liters=Number($('seaVibeFuelTopupLitersInput').value),value=Number($('seaVibeFuelTopupValueInput').value),notes=$('seaVibeFuelTopupNotes').value,transactionDate=$('seaVibeFuelTopupDate').value;if(editingFuelTopupId){await window.SeaVibeService.updateFuelTopup(editingFuelTopupId,liters,value,notes,transactionDate);showStatus('seaVibeFuelStatus',t('seaVibe.fuel.topupUpdated','تم تعديل شحن البنزين.'),'success');}else{await window.SeaVibeService.topupFuel(liters,value,notes,transactionDate);showStatus('seaVibeFuelStatus',t('seaVibe.fuel.topupSaved','تم شحن رصيد البنزين.'),'success');}resetFuelTopupForm();form.classList.add('hidden');renderFuel();renderTreasury();}catch(err){showStatus('seaVibeFuelStatus',err.message,'error');}});
